import{_ as i,c as n,o as t,a5 as s}from"./chunks/framework.DorIfSpC.js";const u=JSON.parse('{"title":"從零理解神經網路（一）：一個神經元是如何思考的？","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/learning/micrograd_visualize/01-multi-input-neuron"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/learning/micrograd_visualize/01-multi-input-neuron"}],["meta",{"property":"og:title","content":"從零理解神經網路（一）：一個神經元是如何思考的？ | 星智未來"}],["meta",{"name":"twitter:title","content":"從零理解神經網路（一）：一個神經元是如何思考的？ | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"從零理解神經網路（一）：一個神經元是如何思考的？\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/learning/micrograd_visualize/01-multi-input-neuron\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/learning/micrograd_visualize/01-multi-input-neuron\\"}}"]]},"headers":[],"relativePath":"learning/micrograd_visualize/01-multi-input-neuron.md","filePath":"learning/micrograd_visualize/01-multi-input-neuron.md","lastUpdated":1786596283000}'),l={name:"learning/micrograd_visualize/01-multi-input-neuron.md"};function e(p,a,o,r,c,h){return t(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="從零理解神經網路-一-一個神經元是如何思考的" tabindex="-1">從零理解神經網路（一）：一個神經元是如何思考的？ <a class="header-anchor" href="#從零理解神經網路-一-一個神經元是如何思考的" aria-label="Permalink to &quot;從零理解神經網路（一）：一個神經元是如何思考的？&quot;">​</a></h1><blockquote><p>本文是「從零理解神經網路」系列的第一篇。我們將從最基本的單元——神經元——開始，理解深度學習的本質。</p></blockquote><h2 id="前言-為什麼要從神經元開始" tabindex="-1">前言：為什麼要從神經元開始？ <a class="header-anchor" href="#前言-為什麼要從神經元開始" aria-label="Permalink to &quot;前言：為什麼要從神經元開始？&quot;">​</a></h2><p>當我們聽到「深度學習」、「神經網路」這些詞彙時，很容易被其複雜性嚇到。但事實上，不管多麼龐大的神經網路，都是由一個個簡單的「神經元」組成的。</p><p>就像理解一棟大樓要先理解一塊磚頭，理解神經網路要先理解一個神經元。</p><h2 id="生物神經元的啟發" tabindex="-1">生物神經元的啟發 <a class="header-anchor" href="#生物神經元的啟發" aria-label="Permalink to &quot;生物神經元的啟發&quot;">​</a></h2><p>人工神經元的設計靈感來自於我們大腦中的生物神經元。讓我們先看看生物神經元是怎麼運作的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>         樹突（接收信號）</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>    突觸（調節信號強度）</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>      細胞體（整合信號）</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>      閾值判斷（要不要發射？）</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>        軸突（發送信號）</span></span></code></pre></div><p>生物神經元的工作流程：</p><ol><li><strong>樹突</strong>從其他神經元接收電信號</li><li><strong>突觸</strong>會調節每個輸入信號的強度（有些連接強，有些弱）</li><li><strong>細胞體</strong>把所有信號加總起來</li><li>如果總和超過某個<strong>閾值</strong>，神經元就會「發射」，把信號傳給下一個神經元</li></ol><p>人工神經元完美複製了這個機制。</p><h2 id="人工神經元的數學模型" tabindex="-1">人工神經元的數學模型 <a class="header-anchor" href="#人工神經元的數學模型" aria-label="Permalink to &quot;人工神經元的數學模型&quot;">​</a></h2><p>一個接收 3 個輸入的神經元，其運算過程可以寫成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>輸出 = 激活函數( w₁×x₁ + w₂×x₂ + w₃×x₃ + b )</span></span></code></pre></div><p>讓我們拆解每個部分：</p><h3 id="_1-輸入-inputs-x1-x2-x3" tabindex="-1">1. 輸入（Inputs）：x₁, x₂, x₃ <a class="header-anchor" href="#_1-輸入-inputs-x1-x2-x3" aria-label="Permalink to &quot;1. 輸入（Inputs）：x₁, x₂, x₃&quot;">​</a></h3><p>這就是神經元接收到的「原始資料」。</p><p>舉個例子，如果我們要判斷一個人是否會買某個產品：</p><ul><li>x₁ = 年齡（例如 30）</li><li>x₂ = 收入（例如 50000）</li><li>x₃ = 過去購買次數（例如 5）</li></ul><h3 id="_2-權重-weights-w1-w2-w3" tabindex="-1">2. 權重（Weights）：w₁, w₂, w₃ <a class="header-anchor" href="#_2-權重-weights-w1-w2-w3" aria-label="Permalink to &quot;2. 權重（Weights）：w₁, w₂, w₃&quot;">​</a></h3><p>權重決定了每個輸入的「重要程度」。</p><ul><li><strong>正權重</strong>：這個輸入會增加輸出（正向影響）</li><li><strong>負權重</strong>：這個輸入會減少輸出（負向影響）</li><li><strong>權重絕對值越大</strong>：這個輸入越重要</li></ul><p>例如，如果「過去購買次數」對預測很重要，那麼 w₃ 的絕對值會比較大。</p><h3 id="_3-偏置-bias-b" tabindex="-1">3. 偏置（Bias）：b <a class="header-anchor" href="#_3-偏置-bias-b" aria-label="Permalink to &quot;3. 偏置（Bias）：b&quot;">​</a></h3><p>偏置就像是神經元的「基準線」或「預設傾向」。</p><p>想像一個判斷「要不要出門」的神經元：</p><ul><li>如果 b 是正的大數值，表示這個神經元「預設想出門」，需要很多負面因素才會改變主意</li><li>如果 b 是負的大數值，表示這個神經元「預設不想出門」，需要很多正面因素才會出門</li></ul><h3 id="_4-加權和-weighted-sum-z" tabindex="-1">4. 加權和（Weighted Sum）：z <a class="header-anchor" href="#_4-加權和-weighted-sum-z" aria-label="Permalink to &quot;4. 加權和（Weighted Sum）：z&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>z = w₁×x₁ + w₂×x₂ + w₃×x₃ + b</span></span></code></pre></div><p>這一步把所有輸入「整合」成一個數字。你可以把它想成「投票」：</p><ul><li>每個輸入 xᵢ 投一票</li><li>但每票的影響力由權重 wᵢ 決定</li><li>最後加上偏置 b 作為基準</li></ul><h3 id="_5-激活函數-activation-function" tabindex="-1">5. 激活函數（Activation Function） <a class="header-anchor" href="#_5-激活函數-activation-function" aria-label="Permalink to &quot;5. 激活函數（Activation Function）&quot;">​</a></h3><p>加權和 z 可以是任意數字（從負無窮到正無窮），但我們通常希望輸出在某個範圍內。這就是激活函數的作用。</p><p>常見的激活函數：</p><p><strong>Sigmoid</strong>：把輸出壓縮到 (0, 1) 之間</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>σ(z) = 1 / (1 + e^(-z))</span></span></code></pre></div><ul><li>輸出像「機率」</li><li>z 很大 → 輸出接近 1</li><li>z 很小 → 輸出接近 0</li></ul><p><strong>Tanh</strong>：把輸出壓縮到 (-1, 1) 之間</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tanh(z) = (e^z - e^(-z)) / (e^z + e^(-z))</span></span></code></pre></div><p><strong>ReLU</strong>：簡單粗暴，負的變 0，正的不變</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ReLU(z) = max(0, z)</span></span></code></pre></div><h2 id="一個具體例子" tabindex="-1">一個具體例子 <a class="header-anchor" href="#一個具體例子" aria-label="Permalink to &quot;一個具體例子&quot;">​</a></h2><p>假設我們有一個神經元，要判斷「這隻動物是不是貓」：</p><p><strong>輸入：</strong></p><ul><li>x₁ = 有鬍鬚嗎？（1 = 有，0 = 沒有）→ 值為 1</li><li>x₂ = 會汪汪叫嗎？（1 = 會，0 = 不會）→ 值為 0</li><li>x₃ = 體型小嗎？（1 = 小，0 = 大）→ 值為 1</li></ul><p><strong>權重（假設已經訓練好）：</strong></p><ul><li>w₁ = 0.8（有鬍鬚 → 偏向是貓）</li><li>w₂ = -0.9（會汪汪叫 → 偏向不是貓）</li><li>w₃ = 0.3（體型小 → 稍微偏向是貓）</li><li>b = -0.2（偏置）</li></ul><p><strong>計算：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>z = 0.8×1 + (-0.9)×0 + 0.3×1 + (-0.2)</span></span>
<span class="line"><span>  = 0.8 + 0 + 0.3 - 0.2</span></span>
<span class="line"><span>  = 0.9</span></span>
<span class="line"><span></span></span>
<span class="line"><span>輸出 = sigmoid(0.9) = 0.71</span></span></code></pre></div><p>結論：這個神經元認為有 71% 的機率是貓。</p><h2 id="神經元的局限性" tabindex="-1">神經元的局限性 <a class="header-anchor" href="#神經元的局限性" aria-label="Permalink to &quot;神經元的局限性&quot;">​</a></h2><p>單個神經元能做的事情其實很有限——它只能學習「線性」的決策邊界。</p><p>想像在一個二維平面上：</p><ul><li>綠點代表「是」</li><li>紅點代表「否」</li></ul><p>單個神經元只能畫一條「直線」來分開它們。</p><p>這就是為什麼我們需要：</p><ol><li><strong>多個神經元</strong>（處理不同特徵）</li><li><strong>多層網路</strong>（組合出複雜的決策邊界）</li><li><strong>非線性激活函數</strong>（讓網路能學習曲線）</li></ol><p>這些我們會在後續文章中深入探討。</p><h2 id="互動視覺化" tabindex="-1">互動視覺化 <a class="header-anchor" href="#互動視覺化" aria-label="Permalink to &quot;互動視覺化&quot;">​</a></h2><p>為了更直觀地理解神經元的運作，我製作了一個互動視覺化工具：</p><p>👉 <a href="/htmls/multi-input-neuron.html" target="_blank">多輸入神經元互動視覺化</a></p><p>在這個工具中，你可以：</p><ul><li>調整輸入值 x₁, x₂, x₃</li><li>調整權重 w₁, w₂, w₃ 和偏置 b</li><li>切換不同的激活函數</li><li>觀察每個輸入的「貢獻」（正向還是負向）</li><li>看到決策邊界的熱力圖</li></ul><p>建議你花幾分鐘玩一玩，感受：</p><ol><li>權重如何影響輸入的重要性</li><li>偏置如何移動決策邊界</li><li>不同激活函數的輸出差異</li></ol><h2 id="小結" tabindex="-1">小結 <a class="header-anchor" href="#小結" aria-label="Permalink to &quot;小結&quot;">​</a></h2><p>今天我們學到了：</p><ol><li><strong>神經元是神經網路的基本單元</strong>，靈感來自生物神經元</li><li><strong>神經元的運算</strong>：輸出 = 激活函數(Σ wᵢxᵢ + b)</li><li><strong>權重</strong>決定每個輸入的重要性和方向（正/負影響）</li><li><strong>偏置</strong>是神經元的「預設傾向」</li><li><strong>激活函數</strong>把輸出壓縮到特定範圍</li><li><strong>單個神經元只能學習線性邊界</strong>，這是它的局限</li></ol><h2 id="下一篇預告" tabindex="-1">下一篇預告 <a class="header-anchor" href="#下一篇預告" aria-label="Permalink to &quot;下一篇預告&quot;">​</a></h2><p>單個神經元只能畫直線，那怎麼學習複雜的模式呢？</p><p>下一篇我們會探討<strong>激活函數</strong>——為什麼它是神經網路能夠學習複雜函數的關鍵。我們會回答一個核心問題：<strong>如果沒有非線性激活函數，100 層神經網路和 1 層有什麼區別？</strong></p><hr><p><em>本文是「從零理解神經網路」系列的第一篇。如果你覺得有幫助，歡迎分享給也在學習 ML 的朋友。</em></p>`,73)])])}const g=i(l,[["render",e]]);export{u as __pageData,g as default};
